---@param idolLive3D_SuperTimeLineState_ table
function SuperTimelineV2_14000850_Enter:__init( idolLive3D_SuperTimeLineState_ )
    
    self.idolLive3D_SuperTimeLineState = idolLive3D_SuperTimeLineState_
    self.lastClipId = nil -- 最后一次登记的 clipId

    local allResources = self.idolLive3D_SuperTimeLineState.idolLive3D_InteractiveManager.allResources
    self.fullBlackFXEnv = allResources.fullScreenFXEnvs["_FullBlack_"]

    self.isLeaveClip0 = false -- 离开 clip0 的第一帧
end




-- 需手动调用 Delete()
function SuperTimelineV2_14000850_Enter:__delete()

    self.fullBlackFXEnv:Delete()
end



function SuperTimelineV2_14000850_Enter:StartPlay() 
    self.isLeaveClip0 = false -- 离开 clip0 的第一帧
    -- 进去就 cut 黑幕
    --self.fullBlackFXEnv:StartFadeIn(0) --- 全屏特效 淡入 (不等待)
end 



-- ---@param clipJson_ table @ c# class SuperTimelineClip 内数据
-- ---@param timelineEnv_ table
function SuperTimelineV2_14000850_Enter:AfterPlayClip( clipJson_, timelineEnv_ ) 
    local clipId = tostring(clipJson_.clipId)
    if clipId == "5" then 

        local clipDuration = timelineEnv_.play.duration -- timeline clip 总时长
        local countDownDuration = 5 -- 倒计时总时长, 允许它比 clipDuration 长;

        Events.Broadcast(IdolLive3D_States.EventSuperTL_StartQTE, 
            140008, -- roleId_
            0.5,    -- initSliderVal_
            0.2,    -- reduceSpeed_   0.33
            0.01,  -- minGrowValOnceTouch_ 0.018
            0.1,   -- maxGrowValOnceTouch_ 0.07
            -- countDownParams_
            {       
                startPointTime = Time.time + (clipDuration-countDownDuration),  -- 允许此时间点为: 曾经/现在/未来
                duration = countDownDuration, -- 倒计时总时长
            },
            localize("连续点击屏幕,想办法跟上舞姿步伐")
        )
    end 
end




-- ---@param clipJson_ table @ c# class SuperTimelineClip 内数据
-- ---@param timelineEnv_ table
function SuperTimelineV2_14000850_Enter:SelfUpdate( clipJson_, timelineEnv_ ) 
    local clipId = tostring(clipJson_.clipId)
    local isFirstFrame = (clipId ~= self.lastClipId)
    self.lastClipId = clipId

    -- if clipId == "0" then        
    --     --- clip 0 播放 4秒:
    --     if timelineEnv_.play.totalTime > 4 and self.isLeaveClip0 == false then  
    --         self.isLeaveClip0 = true

    --         -- 先跳入下一个 clip:
    --         local nextClipInfo = clipJson_.nextClipInfos[1]
    --         self.idolLive3D_SuperTimeLineState:PlayClip( nextClipInfo.clipId, false )

    --         CriWareUtils_.PlayMusic( bgm_sheet, bgm_cue_tl )
    --         -- 黑幕淡出
    --         local fadeOutTime = 0.5
    --         self.fullBlackFXEnv:StartFadeOut(fadeOutTime) --- 全屏特效 淡入 (不等待)
    --     end

    if clipId == "5" then 
        -- 只有 clip "5" 是带逻辑的 

        --- clip "5" 播放完一遍了, 根据输赢做出结算, 进入不同分支:
        if timelineEnv_.play.loopInteger > 0 then   
            local rets = {}
            Events.Broadcast(IdolLive3D_States.EventSuperTL_EndQTE, rets )
            ---
            local nextClipInfo = (rets.isSuccess == true) and clipJson_.nextClipInfosMap["success"] or clipJson_.nextClipInfosMap["fail"]
            self.idolLive3D_SuperTimeLineState:PlayClip( nextClipInfo.clipId, false )
        end 
    else
        -- 直接使用通用功能:
        self.idolLive3D_SuperTimeLineState:UpdateLeaveInfos( clipJson_, timelineEnv_ )
        self.idolLive3D_SuperTimeLineState:UpdateNextClipInfos( clipJson_, timelineEnv_ )
    end 
end



function SuperTimelineV2_14000850_Enter:AfterEndProcess( params )
    CriWareUtils_.PlayMusic( bgm_sheet, bgm_cue )
end





